import React, { useEffect, useMemo, useState } from 'react';
import type { TabKey } from '../components/TabNav';
import './Accueil.css';

const slides = [
  { src: '/assets/hero-clean.jpg',   alt: "Équipe +Propre en intervention, surfaces vitrées impeccables" },
  { src: '/assets/hero-clean-2.jpg', alt: "Nettoyage de bureaux, postes de travail impeccables" },
  { src: '/assets/hero-clean-3.jpg', alt: "Hall d’immeuble brillant après l’entretien" },
];

export default function Accueil({ goTo }: { goTo: (k: TabKey) => void }) {
  const [i, setI] = useState(0);
  const reduceMotion = useMemo(
    () => typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches,
    []
  );

  useEffect(() => {
    if (reduceMotion) return;
    const t = setInterval(() => setI(prev => (prev + 1) % slides.length), 4500);
    return () => clearInterval(t);
  }, [reduceMotion]);

  const prev = () => setI(v => (v - 1 + slides.length) % slides.length);
  const next = () => setI(v => (v + 1) % slides.length);

  return (
    <section className="accueil" aria-labelledby="hero">
      <div className="hero-full">
        <div className="slideshow" aria-hidden="true">
          {slides.map((s, idx) => (
            <img
              key={s.src}
              src={s.src}
              alt=""
              className={`slide ${idx === i ? 'active' : ''}`}
              loading={idx === 0 ? 'eager' : 'lazy'}
            />
          ))}

          <button className="slide-btn slide-btn--prev" onClick={prev} aria-label="Image précédente">‹</button>
          <button className="slide-btn slide-btn--next" onClick={next} aria-label="Image suivante">›</button>

          <div className="dots" role="tablist" aria-label="Sélecteur d'image">
            {slides.map((_, idx) => (
              <button
                key={idx}
                role="tab"
                aria-selected={idx === i}
                className={`dot ${idx === i ? 'is-active' : ''}`}
                onClick={() => setI(idx)}
              />
            ))}
          </div>
        </div>

        <div className="hero-content">
          <div className="hero-container">
            <div className="hero-col">
              <h1 id="hero">Le nettoyage pro qui fait briller vos espaces.</h1>
              <p className="lede">
                Bureaux, cabinets médicaux, commerces, copropriétés, locations de courte durée (Airbnb, etc.),
                fins de bail et fins de chantier — on s’occupe de tout, avec des standards d’hygiène élevés
                et des délais maîtrisés.
              </p>

              <div className="cta">
                <button className="btn btn-primary btn-lg" onClick={() => goTo('contact')}>Demander un devis</button>
                <button className="btn btn-ghost btn-lg" onClick={() => goTo('realisations')}>Voir nos réalisations</button>
              </div>

              <div className="kpis kpis-tight" aria-label="Indicateurs de confiance">
                <div className="kpi kpi-chip"><strong>24h</strong><span className="small">Devis sous 24h</span></div>
                <div className="kpi kpi-chip"><strong>7j/7</strong><span className="small">Interventions flexibles</span></div>
                <div className="kpi kpi-chip"><strong>100%</strong><span className="small">Équipe assurée & formée</span></div>
                <div className="kpi kpi-chip"><strong>Éco</strong><span className="small">Produits responsables</span></div>
              </div>
            </div>
          </div>
        </div>

        <div className="hero-ambient" aria-hidden="true"></div>
      </div>

      <div className="cards">
        <div className="card">
          <h3>Service de nettoyage & d’entretien</h3>
          <p className="muted">Des prestations adaptées à votre activité, avec procédures d’hygiène, checklists et contrôle qualité.</p>
          <ul className="services-list" aria-label="Activités">
            <li className="service">Bureaux</li>
            <li className="service">Cabinets médicaux</li>
            <li className="service">Commerces</li>
            <li className="service">Copropriétés</li>
            <li className="service">Locations de courte durée (Airbnb, etc.)</li>
            <li className="service">Fins de bail</li>
            <li className="service">Fins de chantier</li>
          </ul>
        </div>
        <div className="card">
          <h3>Pourquoi +Propre ?</h3>
          <ul className="bullet">
            <li>Plans d’entretien sur-mesure et horaires sans contrainte.</li>
            <li>Traçabilité : checklist d’intervention & contrôle qualité.</li>
            <li>Hygiène stricte (protocoles spécifiques secteurs sensibles).</li>
          </ul>
        </div>
        <div className="card">
          <h3>Zone d’intervention</h3>
          <p className="muted">Île-de-France et alentours — interventions ponctuelles & récurrentes.</p>
          <div className="cta">
            <button className="btn btn-primary" onClick={() => goTo('contact')}>Obtenir un devis</button>
          </div>
        </div>
      </div>
    </section>
  );
}
